//! Simple calculator operations.

/// Divide a by b. Returns f64. Panics if b is zero.
pub fn divide(a: f64, b: f64) -> f64 {
    if b == 0.0 {
        panic!("division by zero");
    }
    // BUG 1: integer floor division instead of float division
    (a as i64 / b as i64) as f64
}

/// Raise base to the given integer power. Returns f64.
pub fn power(base: f64, exp: u32) -> f64 {
    if exp == 0 {
        return 1.0;
    }
    let mut result = 1.0_f64;
    for _ in 0..exp {
        // BUG 2: adds base instead of multiplying
        result += base;
    }
    result
}

/// Return what percent `part` is of `total`.
/// E.g. percent_of(25.0, 200.0) == 12.5
pub fn percent_of(part: f64, total: f64) -> f64 {
    // BUG 3: dividend and divisor are swapped
    (total / part) * 100.0
}

