#[cfg(test)]
mod tests {
    use rust_dirty_calculator::{divide, power, percent_of};

    #[test]
    fn test_divide_exact() {
        assert_eq!(divide(10.0, 4.0), 2.5);
    }

    #[test]
    fn test_divide_whole() {
        assert_eq!(divide(9.0, 3.0), 3.0);
    }

    #[test]
    fn test_power_basic() {
        assert_eq!(power(2.0, 3), 8.0);
    }

    #[test]
    fn test_power_zero_exp() {
        assert_eq!(power(5.0, 0), 1.0);
    }

    #[test]
    fn test_percent_of() {
        assert!((percent_of(25.0, 200.0) - 12.5).abs() < 1e-9);
    }

    #[test]
    fn test_percent_of_half() {
        assert!((percent_of(50.0, 100.0) - 50.0).abs() < 1e-9);
    }
}
